26	    @Mapping(target = "initials", expression = "java(toInitials(owner))")
27	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
28	    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /**
32	     * Format an owner's stored names as {@code 'LastName, FirstName'} for the
33	     * read-only {@code displayName} field returned on the Owner DTO.
34	     */
35	    default String toDisplayName(Owner owner) {
36	        return owner.getLastName() + ", " + owner.getFirstName();
37	    }
38	
39	    /**
40	     * Build the owner's initials as the upper-cased first letters of firstName and
41	     * lastName, dot-separated with a trailing dot (e.g. {@code 'J.S.'}) for the
42	     * read-only {@code initials} field returned on the Owner DTO.
43	     */
44	    default String toInitials(Owner owner) {
45	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
46	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
47	    }
48	
49	    /**
50	     * Derive the owner's read-only {@code locality}: the REGION segment of the owner's
51	     * {@code customerCode} ({@code '<REGION>-<HASH8>'}), the region-and-hash identity the owner is
52	     * assigned at creation. Falls back to resolving the region directly from the owner's postcode
53	     * range first ({@code NSW 2000-2099, VIC 3000-3099, QLD 4000-4099}), then the canonical region
54	     * of the owner's city ({@code Sydney->NSW, Melbourne->VIC, Brisbane->QLD}), else {@code 'UNKNOWN'},
55	     * when the owner has no {@code customerCode} yet. Sourcing it from the identity keeps the
56	     * owner's reported locality and its {@code customerCode} region in lock-step.
57	     */
58	    default String toLocality(Owner owner) {
59	        String customerCode = owner.getCustomerCode();
60	        if (customerCode != null) {
61	            int dash = customerCode.indexOf('-');
62	            if (dash > 0) {
63	                return customerCode.substring(0, dash);
64	            }
65	        }
66	        return PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity());
67	    }
68	
69	    /**
70	     * Derive the owner's read-only {@code contactPreference}: {@code EMAIL} when the owner has an
71	     * email address, otherwise {@code PHONE}.
72	     */
73	    default OwnerDto.ContactPreferenceEnum toContactPreference(Owner owner) {
74	        return owner.getEmail() != null && !owner.getEmail().isBlank()
75	            ? OwnerDto.ContactPreferenceEnum.EMAIL
76	            : OwnerDto.ContactPreferenceEnum.PHONE;
77	    }
