89	     * Normalize a postal address to its canonical form (trimmed and whitespace-collapsed,
90	     * upper-cased, with common street-type abbreviations expanded) so it is stored, returned and
91	     * compared in one shape. Blank-after-normalization is rejected separately by
92	     * {@code AddressValidation} on the inbound DTO, so this only performs the transform the stored
93	     * value needs.
94	     */
95	    @Named("normalizeAddress")
96	    default String normalizeAddress(String address) {
97	        return AddressNormalizer.normalize(address);
98	    }
99	
100	    /**
101	     * Normalize a telephone number to canonical E.164 form (a leading {@code '+'}, country
102	     * code and national digits) so it is stored and returned in one comparable form and
103	     * duplicates can be detected by comparing these values. Format validity is enforced
104	     * separately by {@code TelephoneValidation} on the inbound DTO, so this only performs
105	     * the transform the stored value needs.
106	     */
107	    @Named("normalizeTelephone")
108	    default String normalizeTelephone(String telephone) {
109	        return TelephoneNormalizer.toE164(telephone);
110	    }
111	
112	    /**
113	     * Normalize an email address by trimming surrounding whitespace and lower-casing
114	     * it so it is stored and returned in a canonical form. Syntactic validity is
115	     * enforced separately by {@code @Email} on the inbound DTO, so this only performs
116	     * the transform the stored value needs.
117	     */
118	    @Named("normalizeEmail")
119	    default String normalizeEmail(String email) {
120	        return email == null ? null : email.trim().toLowerCase();
121	    }
122	
123	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
124	
125	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
126	
127	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
128	        OwnerPageDto ownerPageDto = new OwnerPageDto();
129	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
130	        ownerPageDto.setPage(ownerPage.getNumber());
131	        ownerPageDto.setSize(ownerPage.getSize());
132	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
133	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
134	        return ownerPageDto;
